 $options=['method'=>$data===null?'GET':'POST','header'=>$head,'ignore_errors'=>true,'follow_location'=>0,'timeout'=>20];if($data!==null){$options['header'].="Content-Type: application/x-www-form-urlencoded\r\n";$options['content']=http_build_query($data);}
 $body=file_get_contents($base.$path,false,stream_context_create(['http'=>$options]));preg_match('/ ([0-9]{3}) /',$http_response_header[0]??'',$match);return ['code'=>(int)($match[1]??0),'body'=>(string)$body,'headers'=>$http_response_header??[]];
}
